do $$ begin
 if exists(select 1 from bank_sync_expected e left join public.builtin_question_targets t on (t.subject_id,t.unit_id,t.target_id)=(e.subject_id,e.unit_id,e.target_id) where t.content is distinct from e.content) then raise exception 'CATALOG_CHANGED_RECHECK'; end if;
 if exists(select 1 from bank_sync_shared e left join public.published_questions p on p.id=e.id where p.subject_id is distinct from e.subject_id or p.unit_id is distinct from e.unit_id or p.submission_id is distinct from e.submission_id or not p.visible or p.content is distinct from e.before) then raise exception 'SHARED_CHANGED_RECHECK'; end if;
 if exists(select 1 from bank_sync_shared e left join public.question_submissions s on s.id=e.submission_id where s.status is distinct from 'published' or s.content is distinct from e.before) then raise exception 'SUBMISSION_CHANGED_RECHECK'; end if;
 if exists(select 1 from bank_sync_shared e join public.question_replacements r on (r.subject_id,r.unit_id,r.target_id)=(e.subject_id,e.unit_id,e.id)) then raise exception 'SHARED_REPLACEMENT_RECHECK'; end if;
 if exists(select 1 from bank_sync_shared e where not public.collaboration_valid_content(e.after)) then raise exception 'INVALID_SHARED_CONTENT'; end if;
end $$;
insert into public.collaboration_units(subject_id,unit_id) values ('os','u2') on conflict do nothing;
